import { chromium } from 'playwright';import fs from 'fs';import path from 'path';
const BASE='https://www.statesideqm.com',THEME='158900125851',key=process.env.KEY,label=process.env.LABEL,route=process.env.ROUTE,OUT='sep18-sg-local-only-'+key;fs.mkdirSync(path.join(OUT,'screenshots'),{recursive:true});
const statePath=new URL(route,BASE).pathname;
const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});
const blocked=[],allowed=[];
await c.route('**/*',async r=>{const u=new URL(r.request().url());if(u.origin===new URL(BASE).origin&&/\/collections\/[^/]+\/products\.json$/.test(u.pathname)){if(u.pathname===statePath+'/products.json'){allowed.push(u.pathname+u.search);return r.continue()}blocked.push(u.pathname+u.search);return r.abort('blockedbyclient')}return r.continue()});
const p=await c.newPage();p.setDefaultNavigationTimeout(70000);const u=new URL(route,BASE);u.searchParams.set('preview_theme_id',THEME);let resp=null,error=null;try{resp=await p.goto(u.href,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});await p.waitForTimeout(5500)}catch(e){error=String(e?.message||e)}
const row=await p.evaluate(({label,route,themeId})=>{const v=document.querySelector('[data-sqsg-view]');return{label,route,theme:{id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')},cards:[...document.querySelectorAll('[data-sqsg-view] a.sqsg-card')].map(a=>({label:(a.querySelector('strong')?.textContent||'').replace(/\s+/g,' ').trim(),meta:(a.querySelector('small')?.textContent||'').replace(/\s+/g,' ').trim(),href:a.getAttribute('href')||'',display:getComputedStyle(a).display,visibility:getComputedStyle(a).visibility})),viewData:v?[...v.attributes].filter(a=>a.name.startsWith('data-')).reduce((o,a)=>(o[a.name]=a.value,o),{}):{},h1:(document.querySelector('h1')?.textContent||'').replace(/\s+/g,' ').trim(),previewOk:String(window.Shopify?.theme?.id||'')===themeId}}, {label,route,themeId:THEME});row.httpStatus=resp?.status()??null;row.error=error;row.blocked=blocked;row.allowed=allowed;fs.writeFileSync(path.join(OUT,'result.json'),JSON.stringify(row,null,2));await p.screenshot({path:path.join(OUT,'screenshots','local-only.png'),fullPage:false});console.log('SGLOCALONLY',JSON.stringify(row));await c.close();await b.close();